class HotelGuestExperienceSeeder extends Seeder { public function run():void { foreach(Property::where('is_active',1)->get() as $property){$slug=Str::slug($property->code?:$property->name);PropertyWebSetting::firstOrCreate(['property_id'=>$property->id],['slug'=>$slug,'headline'=>'Stay, dine and experience '.$property->name,'intro'=>'Book your room directly, manage your stay and enjoy seamless hotel services.','contact_phone'=>null,'contact_email'=>null,'online_booking_enabled'=>true,'digital_checkin_enabled'=>true,'default_deposit_percent'=>30]);foreach([['Airport Pickup','Private airport pickup/drop-off service',80000],['Breakfast','Breakfast package per guest',35000],['Extra Bed','Additional bed for the stay',60000],['Late Checkout','Late checkout subject to availability',75000]] as [$n,$d,$p])BookingAddon::firstOrCreate(['property_id'=>$property->id,'name'=>$n],['description'=>$d,'price'=>$p,'charge_basis'=>'per_booking','is_active'=>true]);} } }
